SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, job_title, COUNT(DISTINCT salary) AS unique_levels, MIN(salary) AS min_salary FROM employees WHERE hire_date BETWEEN '2023-07-01' AND '2025-04-12' AND manager_id IS NULL AND is_remote = TRUE GROUP BY 1, 2 HAVING MIN(salary) < 82000 ORDER BY unique_levels DESC
